# Pure Python 3, no imports, no I/O, no prints, exact integer arithmetic.
# Fails closed: raises on any failed check; returns True only if all hold.

def verify(witness):
    p = witness["p"]
    if p < 2:
        raise ValueError("p not prime-candidate")
    d = 2
    while d * d <= p:
        if p % d == 0:
            raise ValueError("p composite")
        d += 1
    for k in witness["k_values"]:
        if k < 2:
            raise ValueError("k below canonical range")
        # literal reading: k intervals I_1..I_k (1-indexed), each singleton {1}
        for i in range(1, k + 1):
            prod = 1  # product of elements of {1}
            if prod % p != 1:
                raise ValueError("interval product not 1 mod p")
    return True

# Embedded witness check; any failure raises (nonzero exit = FAIL).
WITNESS = {
    "p": 2,
    "k_values": [2, 3, 4, 5, 10, 100],
}
verify(WITNESS)
